// SECTION = { section, subsections:[ { subsection, title, section_job, spine, logic_chain_validated:{}, paragraphs:[ {pid, intent, thin_claim, guardrails:[], props:[ {prop_id, type, verdict, statement, role} ] } ] } ] }
